  final int? basisPoints;
  final Map<String, Object?>? fixedAmount;

  const TipDraft({
    required this.kind,
    required this.basisPoints,
    required this.fixedAmount,
  });

  factory TipDraft.fromJson(Map<String, Object?> json) => TipDraft(
      kind: json["kind"] as String,
      basisPoints: json["basisPoints"] == null ? null : (json["basisPoints"] as num).toInt(),
      fixedAmount: json["fixedAmount"] == null ? null : json["fixedAmount"] as Map<String, Object?>,
  );

  Map<String, Object?> toJson() => {
      "kind": kind,
      "basisPoints": basisPoints,
      "fixedAmount": fixedAmount,
  };
}

final class TipPolicy {
  final bool enabled;
  final List<int> presetBasisPoints;
  final bool customPercentageEnabled;
  final bool customFixedEnabled;
  final Map<String, Object?> maximumTip;
  final String? requiredPermission;
  final String version;

  const TipPolicy({
    required this.enabled,
    required this.presetBasisPoints,
    required this.customPercentageEnabled,
    required this.customFixedEnabled,
    required this.maximumTip,
    required this.requiredPermission,
    required this.version,
  });

  factory TipPolicy.fromJson(Map<String, Object?> json) => TipPolicy(
      enabled: json["enabled"] as bool,
      presetBasisPoints: (json["presetBasisPoints"] as List<Object?>).cast<int>(),
      customPercentageEnabled: json["customPercentageEnabled"] as bool,
      customFixedEnabled: json["customFixedEnabled"] as bool,
      maximumTip: json["maximumTip"] as Map<String, Object?>,
      requiredPermission: json["requiredPermission"] == null ? null : json["requiredPermission"] as String,
      version: json["version"] as String,
  );

  Map<String, Object?> toJson() => {
      "enabled": enabled,
      "presetBasisPoints": presetBasisPoints,
      "customPercentageEnabled": customPercentageEnabled,
      "customFixedEnabled": customFixedEnabled,
      "maximumTip": maximumTip,
      "requiredPermission": requiredPermission,
      "version": version,
  };
}

